{
  "interpretation": {
    "name": "Line1NutrunnerTighteningWithReturn",
    "scope": {"line": 1, "station": "st1", "tool": "NR7", "variant": "F25"},
    "goal": "Bring the shared nutrunner NR7 to station st1, tighten the F25 fasteners with the MES program, evaluate and record the result, then return the tool to the crib and release it.",
    "constraints": [
      "NR7 is reserved before any use and released only after it is back in the crib",
      "NR7 must be at st1 (transport-tool to 'station' completed) before configure-tool and tighten-fasteners",
      "The tightening program comes only from get-program; no torque or tolerance literals appear in the Recipe",
      "The tightening must be evaluated and recorded for traceability",
      "transport-tool Steps are delegated to agvexecutor",
      "Every tool-using Step depends on reserve-tool so the lease is renewed before use"
    ],
    "preference": "",
    "priority": "normal",
    "horizon": "single execution, now",
    "requested_capabilities": [],
    "omit_services": []
  },
  "recipe": {
    "name": "line1-nr7-tightening-f25",
    "first_action": "prepare",
    "actions": [
      {
        "name": "prepare",
        "next": "deliver",
        "steps": [
          {
            "name": "reserve",
            "service": "reserve-tool",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          },
          {
            "name": "get-program",
            "service": "get-program",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "deliver",
        "next": "tighten",
        "steps": [
          {
            "name": "transport-to-station",
            "service": "transport-tool",
            "next": [],
            "dep": ["reserve"],
            "executor": "agvexecutor",
            "params": {"to": "station"}
          }
        ]
      },
      {
        "name": "tighten",
        "next": "finish",
        "steps": [
          {
            "name": "configure",
            "service": "configure-tool",
            "next": ["tighten-fasteners"],
            "dep": ["get-program", "reserve"],
            "executor": null,
            "params": {}
          },
          {
            "name": "tighten-fasteners",
            "service": "tighten-fasteners",
            "next": ["evaluate", "record"],
            "dep": ["configure", "reserve"],
            "executor": null,
            "params": {}
          },
          {
            "name": "evaluate",
            "service": "evaluate-tightening",
            "next": [],
            "dep": ["tighten-fasteners", "get-program"],
            "executor": null,
            "params": {}
          },
          {
            "name": "record",
            "service": "record-tightening",
            "next": [],
            "dep": ["tighten-fasteners"],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "finish",
        "next": null,
        "steps": [
          {
            "name": "transport-to-crib",
            "service": "transport-tool",
            "next": ["release"],
            "dep": ["reserve"],
            "executor": "agvexecutor",
            "params": {"to": "crib"}
          },
          {
            "name": "release",
            "service": "release-tool",
            "next": [],
            "dep": ["reserve"],
            "executor": null,
            "params": {}
          }
        ]
      }
    ]
  }
}
